entries[179937] = { ["name"] = "Splitter der aufkeimenden Ambition", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 tag (Realzeit)\nBenutzen: Erhöht Eure Hauptwert um 27 , verringert aber Eure maximale Gesundheit um 5%. Hält 1 Min. lang an. Bis zu 10-mal stapelbar. Kann nur im Freien in den Schattenlanden verwendet werden.\n5 Aufladungen\n\"Ambition kann Besonnenheit übertreffen.\"\nVerkaufspreis:" }
entries[179938] = { ["name"] = "Zerbröckelnde Stolzextraktoren", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 tag (Realzeit)\nBenutzen: Entzieht einem Gegner seine Vitalität, was ihm 20 Sek. lang alle 5 Sek. 3205 Schattenschaden zufügt und Euch dabei jeweils um 7363 Gesundheit heilt. Kann nur im Freien in den Schattenlanden verwendet werden. (1 Min Abklingzeit)\n5 Aufladungen\nVerkaufspreis:" }
entries[179939] = { ["name"] = "Zuckender Spinnensack", ["text"] = "Wird beim Aufheben gebunden\nDauer: 1 tag (Realzeit)\nBenutzen: Werft den zuckenden Spinnensack und seht, wie viele Spinnen sich auf Euer Ziel stürzen! Kann nur im Freien in den Schattenlanden verwendet werden. (2 Min Abklingzeit)\n\"Oh, sie sind zum Schlüpfen bereit!\"\nVerkaufspreis:" }
