entries[180263] = { ["name"] = "Traumlichtrunenhirsch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Runenhirsche werden jenen gewährt, die der Winterkönigin und dem Hof der Nacht ihre Dienste versichert haben.\"\nPakt:\nNachtfae\nZone:\nArdenwald" }
entries[180264] = { ["name"] = "Monströse Unterstützung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört Emeni, damit sie Euch 2 Min. lang im Kampf unterstützt. Kann nur im Freien in den Schattenlanden verwendet werden. (10 Min Abklingzeit)\n60 ( 60)\n\"Darum kümmert sich Emeni!\"\nVerkaufspreis:" }
entries[180266] = { ["name"] = "Stygischer Vorschlaghammer", ["text"] = "Questgegenstand\n\"Ein Hammer, der Steingräber in Zovaals Kessel zertrümmern kann.\"" }
entries[180267] = { ["name"] = "Klein Eddie", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ruft Klein Eddie für 5 Min. zu Besuch herbei. Viel Glück damit, ihn wieder loszuwerden! (1 Min Abklingzeit)\n\"Niemand mag Eddie.\"\nVerkaufspreis:" }
entries[180269] = { ["name"] = "Altheras Bericht", ["text"] = "Questgegenstand\n\"Details über die Rückkehr der Geißel, darunter Gegnertaktiken, Informationen von Spähern und Verluste.\"" }
entries[180270] = { ["name"] = "Käfigschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 tag\nBenutzen: Öffnet einen Haustierkäfig im Kelchdistrikt." }
entries[180271] = { ["name"] = "Strähnige Spore", ["text"] = "Questgegenstand\n\"Eine strähnige, mächtige Spore.\"" }
entries[180272] = { ["name"] = "Schlüssel zu den Oberen Ebenen", ["text"] = "Questgegenstand\n\"Aus stygischen Metallen geschmiedet und mit bösen Siegeln verstärkt.\"" }
entries[180273] = { ["name"] = "Kummerfluch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Schwert\n15 - 26 Schaden Geschwindigkeit 3.60\n(5.7 Schaden pro Sekunde)\n+8 Stärke\n+11 Ausdauer\nErhöht Eure Tempowertung um + 5.\n+ 10 Vielseitigkeit\nHaltbarkeit 120 / 120\nAnlegen: Eure automatischen Angriffe haben eine Chance, geringere Kreaturen mit weniger als 20% Gesundheit sofort hinzurichten. (Procchance: 20%)\nVerkaufspreis:" }
entries[180274] = { ["name"] = "Fackel", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Wirft eine Fackel auf Gormeiersäcke in der Nähe. (5 Sek. Abklingzeit)" }
entries[180275] = { ["name"] = "Konstruktverkleidung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verkleidet Euch als kleines Konstrukt, sodass Ihr Euch in den meisten Bereichen des Hauses der Konstrukte gefahrlos bewegen könnt. (1 Min Abklingzeit)\n\"Fast so gut wie das Original.\"\nVerkaufspreis:" }
