entries[180413] = { ["name"] = "Schattenblattrunenhirsch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmstufe 23\nVerkaufspreis:\n\"Die Schattenblattrunenhirsche werden von der Wilden Jagd sowohl wegen ihrer Schönheit als auch ihrer Wildheit gezüchtet. Sie stürmen furchtlos in den Bau eines jeden Raubtiers.\"\nPakt:\nNachtfae\nZone:\nArdenwald" }
entries[180414] = { ["name"] = "Runenhirsch des Erweckers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Runenhirsche ruhen gerne in der Nähe von Wildsamen. Die Erwecker glauben, dass sie die Träume der Schlafenden hören. Während ihrer Wacht zeigen Runenhirsche ein breites Spektrum an Emotionen, die Träume und Alpträume der Geister darin wiedergeben.\"\nPakt:\nNachtfae\nZone:\nArdenwald" }
entries[180415] = { ["name"] = "Winterbornrunenhirsch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Hof der Nacht\n- Respektvoll\nIhr müsst Mitglied des Pakts der Nachtfae sein.\nVerkaufspreis:\n\"Winterbornrunenhirsche sind von der Winterkönigin selbst gesegnet. Ihre Runen leuchten hell, wenn Raubtiere in der Nähe sind, und warnen so die gesamte Herde.\"\nPakt:\nNachtfae\nZone:\nArdenwald" }
