entries[180449] = { ["name"] = "Fehlgeschlagenes Experiment", ["text"] = "\"Die Gestaltung ist komplex und schwer verständlich. Auch nach näherer Untersuchung lässt sich kein Verwendungszweck erkennen.\"\nVerkaufspreis:" }
entries[180450] = { ["name"] = "Verschiedene Bolzen", ["text"] = "\"Ein Haufen Extrabolzen... Die müssen doch zu irgendetwas gut sein, oder?!\"\nVerkaufspreis:" }
entries[180451] = { ["name"] = "Sündensteinfragment eines Großinquisitors", ["text"] = "Wird beim Aufheben gebunden\n\"Archivar Fane braucht dies, um Großinquisitorensündensteine wiederherzustellen, die es Euch erlauben, die gefährlichsten Inquisitoren in den Hallen der Sühne zu jagen.\"\nVerkaufspreis:" }
entries[180452] = { ["name"] = "Speer der Kalliope", ["text"] = "Questgegenstand\n\"Das ist wahrscheinlich der beeindruckendste Speer, den Ihr jemals gesehen habt.\"" }
entries[180453] = { ["name"] = "Sie hatte ein Herz aus Stein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Ein mit steinerner Hand verfasstes Gedicht, das trotz seiner schlichten Prosa irgendwie ergreifend ist.\"" }
