entries[180581] = { ["name"] = "Hoffnungsvernichtergargon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Er war einst das treue Reittier eines Lordregenten des Hauses Dornfluch, stellte sich dann aber gegen ihn und sein Gefolge. Mitglieder von Haus Dornfluch munkeln nun über einen im Dunklen lauernden Gargon, der Venthyr auflauert, die sich in die finsteren Bereiche des Kelchdistrikts von Revendreth begeben.\"\nPakt:\nVenthyr\nZone:\nRevendreth" }
entries[180582] = { ["name"] = "Fliegerleine des Endmorasts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen Flieger des Endmorasts beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese fliegenden Verschlinger kamen durch Portale, über die nur wenig bekannt ist. Sie haben ein Zuhause im Endmorast von Revendreth gefunden, wo sie sich von latenter Anima ernähren.\"\nBeute von:\nFamu der Unendliche\nZone:\nRevendreth" }
entries[180583] = { ["name"] = "Beeinflussbare Fresserbrut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Ein beeindruckender Fresser. Vielleicht findet Ihr ja eine Möglichkeit, seine Loyalität zu gewinnen...\"" }
