entries[180594] = { ["name"] = "Verhärteter Knochen", ["text"] = "Aufgestiegenenhandwerk\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Diese Knochen sind mit der Zeit durch das Wetter und die allgemeine Abnutzung stark verwittert. Man erkennt gut, dass sie von maldraxxischen Kreaturen mit freiliegenden Knochen stammen.\"\nVerkaufspreis:" }
entries[180595] = { ["name"] = "Nachtgeschmiedeter Stahl", ["text"] = "Aufgestiegenenhandwerk\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Ein unglaubliches, von den Venthyr geschmiedetes Metall, das oft bei der Herstellung ihrer Rüstungen und Klingen verwendet wird.\"\nVerkaufspreis:" }
