entries[180660] = { ["name"] = "Dunkelturmpergamente: Sofortverwandler", ["text"] = "Wird beim Aufheben gebunden\nDauer: 1 tag (Realzeit)\nBenutzen: Verwandelt das Ziel (Warnung: Sicherheitshinweise noch ausstehend) in ein Huhn, das 10 Sek. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden bricht den Effekt ab. Es kann nur jeweils 1 Ziel betroffen sein.\n\nWirkt nur bei Wildtieren, Humanoiden und Kleintieren bis zu Stufe 60. Kann nur im Freien in den Schattenlanden verwendet werden.\nVerkaufspreis:" }
entries[180661] = { ["name"] = "Dunkelturmpergamente: Widerwärtiges Gebrechen", ["text"] = "Wird beim Aufheben gebunden\nDauer: 1 tag (Realzeit)\nBenutzen: Verursacht 25 Sek. lang alle 5 Sek. 312 Schattenschaden. Warnung: Fügt zusätzlich alle 5 Sek. allen Gegnern und Verbündeten innerhalb von 8 Metern um das Ziel 160 Schattenschaden zu. Kann nur im Freien in den Schattenlanden verwendet werden. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
