entries[180721] = { ["name"] = "Verzauberter Traumlichtrunenhirsch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die majestätischen Runenhirsche sind mit ihren kunstvollen Geweihen in der Lage, dem Umgebungslicht des Ardenwalds Anima zu entziehen. Die Anima dient ihnen als Nahrung und verleiht ihnen Geschwindigkeit und Magie.\"\nPakt:\nNachtfae\nZone:\nArdenwald" }
entries[180722] = { ["name"] = "Verzauberter Schattenblattrunenhirsch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmstufe 39\nVerkaufspreis:\n\"Ein Schattenblattrunenhirsch ist in der Lage, so mächtige Kreaturen wie eine Gormmatriarchin aufzuspießen, um seine Herde zu verteidigen. Die Wilde Jagd reitet auf ihnen in gefährliche Gegenden der Schattenlande, um ihr Reich vor jenen zu beschützen, die die Wildnis bedrohen.\"\nPakt:\nNachtfae\nZone:\nArdenwald" }
entries[180723] = { ["name"] = "Verzauberter Runenhirsch des Erweckers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Runenhirsche der Erwecker beschützen ihre Wildsamenhaine mit aller Kraft. Als der Niedergang der Haine begann, sind viele Runenhirsche in wilde Raserei verfallen.\"\nPakt:\nNachtfae\nZone:\nArdenwald" }
entries[180724] = { ["name"] = "Verzauberter Winterbornrunenhirsch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Marasmius\n- Respektvoll\nVerkaufspreis:\n\"Winterbornrunenhirsche sind das bevorzugte Reittier der Winterkönigin selbst. Sie erweist die besondere Gunst einer solchen Kreatur nur ihren ausgewählten Favoriten.\"\nPakt:\nNachtfae\nZone:\nArdenwald" }
entries[180725] = { ["name"] = "Stachelschlundhainmalmer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Sprigganreiter binden Stücke animafreier Überreste an Stockenden vor ihre Gormreittiere, um diese zu lenken. Es ist... keine hohe Kunst.\"\nBeute von:\nGormzähmer Tizo\nZone:\nArdenwald" }
entries[180726] = { ["name"] = "Blasser Säureschlund", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nIhr benötigt einen ehrfürchtigen Ruf bei den Flickmeistern.\nVerdient den Erfolg \"Nur das Notwendigste\", um dieses Reittier zu kaufen.\nVerkaufspreis:\n\"Die Säure, die im Sekret dieser Kreatur vorhanden ist, hat die Farbe ihres Panzers weggeätzt. Dadurch ist ein auffälliger schneeweißer Farbton entstanden.\"\nPaktfeature:\nDer Gluthof\nPakt:\nVenthyr\n\nPaktfeature:\nKonservatorium der Königin\nPakt:\nNachtfae\n\nPaktfeature:\nPfad des Aufstiegs\nPakt:\nKyrianer\n\nPaktfeature:\nMonstrositätenfabrik\nPakt:\nNekrolords" }
entries[180727] = { ["name"] = "Schimmernebelläufer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Boshafte Spriggans und die Talläufer verbindet eine natürliche Feindseligkeit. Kein Talläufer würde sich dazu herablassen, einen Sprigganreiter aufsitzen zu lassen, da sie deren innere Böswilligkeit spüren. Dies erzürnt die Spriggantrickser, die ein krankhaftes Vergnügen darin finden, diesen majestätischen Kreaturen grausame Streiche zu spielen.\"\nGebiet:\nNebelschleierdickicht\nZone:\nArdenwald" }
entries[180728] = { ["name"] = "Schneller Düsterhuf", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die Balladen des Ardenwalds behaupten, dass die Geburt eines Finsterläufers die Ankunft eines besonders wohlwollenden wilden Gottes einläutet. Einen Finsterläufer zu sehen, ist aus diesem Grund Segen und Fluch zugleich.\"\nBeute von:\nNachtmähre\nZone:\nArdenwald" }
entries[180729] = { ["name"] = "Dämmerflatterardenmotte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Die Wilde Jagd\n- Ehrfürchtig\nVerkaufspreis:\n\"Diese Ardenmotten bevorzugen die dunklen und feuchten Wälder im Nordwesten des Ardenwalds, in denen Pilzkolonien ohne Unterlass erblühen.\"\nVerkäufer:\nAithlyn\nZone:\nArdenwald\nFraktion:\nDie Wilde Jagd - Ehrfürchtig\nKosten:\n30." }
entries[180730] = { ["name"] = "Wilder Glimmerpelzstreuner", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Das glänzende grüne Fell dieses Streuners hebt sich vom Blau und Lila des Ardenwalds ab, wodurch es für andere seiner Art viel leichter in den Mitternachtswäldern erkennbar ist.\"\nBeute von:\nValfir der Unerbittliche\nPakt:\nNachtfae\nZone:\nArdenwald" }
entries[180731] = { ["name"] = "Wildsamenwiege", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die wertvollste Fracht des ganzen Ardenwalds, die Wildsamen, werden in diesem liebevoll gestalteten Wagen transportiert. Er ist von Anima durchdrungen, wodurch er über den Boden schweben kann.\"\nSchatz:\nTruhe des Mondes\nZone:\nArdenwald" }
