entries[180748] = { ["name"] = "Seidige Schimmermotte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nNehmt an sieben verschiedenen Aufführungen im Sternseeamphitheater teil.\nVerkaufspreis:\n\"Die Motten des Ardenwalds spielen eine zentrale Rolle in seinem Ökosystem, indem sie Sporen, Anima und Pollen in die unterschiedlichen Teile des Waldes tragen. So versorgen sie die tiefer lebenden Bewohner mit Nahrung und Variation.\"\nVerkäufer:\nKassenmeister Salorn\nZone:\nArdenwald\nKosten:\n5.000" }
