entries[180761] = { ["name"] = "Phalynx der Loyalität", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Manche Aufgestiegene halten sich einen Phalynx als Haustier. Im Gegensatz zum Larion hat er zwar kein Fell, doch er besitzt den Vorteil, dass er wahrscheinlich nicht Eure anderen Haustiere frisst.\"\nPakt:\nKyrianer\nZone:\nBastion" }
entries[180762] = { ["name"] = "Phalynx der Demut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der Phalynx verweigert das Apportieren. Woran das liegt, ist nicht bekannt.\"\nPakt:\nKyrianer\nZone:\nBastion" }
entries[180763] = { ["name"] = "Phalynx des Mutes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der Phalynx gilt als würdiger Gefährte und als flinker Gegner, gegen den man seine Reflexe auf die Probe stellen kann.\"\nPakt:\nKyrianer\nZone:\nBastion" }
entries[180764] = { ["name"] = "Phalynx der Reinheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmstufe 23\n\n\"Über die Ursprünge der Phalynxtechnologie ist nur wenig bekannt, denn die Lehre ihrer Geheimnisse ähnelt eher einer Religion als einer Ingenieurskunst.\"\nPakt:\nKyrianer\nZone:\nBastion" }
entries[180765] = { ["name"] = "Ewiger Phalynx der Reinheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmstufe 39\n\n\"Der gepanzerte Phalynx ist ein beliebter Gefährte der mächtigsten Krieger der Aufgestiegenen, da er im Kampf so furchtlos wie tödlich zu Werke geht.\"\nPakt:\nKyrianer\nZone:\nBastion" }
entries[180766] = { ["name"] = "Ewiger Phalynx des Mutes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Um eines dieser funkelnden Reittiere zu schmieden, sind viele Barren Güldenit erforderlich. Doch allein ihr Anblick ist die in das Sammeln des Güldenits investierte Zeit schon wert.\"\nPakt:\nKyrianer\nZone:\nBastion" }
entries[180767] = { ["name"] = "Ewiger Phalynx der Loyalität", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerdient den Erfolg \"Todesvierschmähte\", um dieses Reittier zu kaufen.\n\n\"Gepanzerte Phalynx sind ein Wunderwerk provostscher Ingenieurskunst. Sie sind so selten wie atemberaubend.\"\nPakt:\nKyrianer\nZone:\nBastion" }
entries[180768] = { ["name"] = "Ewiger Phalynx der Demut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerdient den Erfolg \"Von den Meistern lernen\", um dieses Reittier zu kaufen.\n\n\"Wenn ein gepanzerter Phalynx geschmiedet wird, klatschen die Provosten ihre Hämmer zusammen, um ihre Hochachtung vor der dazu erforderlichen Ingenieurskunst zum Ausdruck zu bringen.\"\nPakt:\nKyrianer\nZone:\nBastion" }
entries[180769] = { ["name"] = "Gebrochener Steinflügel", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[180771] = { ["name"] = "Trank der ungewöhnlichen Stärke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Erhöht Eure Stärke 25 Sek. lang um 10. (2 Min Abklingzeit)\n\"Ein billiges leistungssteigerndes Mittel, das bei Arenakämpfern beliebt ist.\"\nVerkaufspreis:" }
entries[180772] = { ["name"] = "Silberwindlarion", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese Gabe des Silberwinds wird nur denen zuteil, die überall nach der Weisheit der Bastion suchen.\"\nSchatz:\nGabe des Silberwinds\nZone:\nBastion" }
entries[180773] = { ["name"] = "Sonnentänzer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser sonnengebadete Renner galoppiert sorgenfrei auf Lichtstrahlen.\"\nBeute:\nZone:\nBastion" }
entries[180774] = { ["name"] = "Konservierte Beeren", ["text"] = "Wird beim Aufheben gebunden\n\"Diese getrockneten Beeren sind runzelig und versengt. Sie wurden in einer toten Welt gesammelt.\"\nVerkaufspreis:" }
entries[180775] = { ["name"] = "Erinnerung an Zuhause", ["text"] = "Questgegenstand\n\"Diese getrockneten Beeren sind runzelig und versengt. Sie wurden in einer toten Welt gesammelt.\"" }
entries[180777] = { ["name"] = "In Thros geschmiedeter Schlüssel", ["text"] = "Questgegenstand\n\"Öffnet die Tür zu Kivarrs Käfig.\"" }
entries[180778] = { ["name"] = "Gefäß des Ardenwalds", ["text"] = "Questgegenstand\n\"Weidenblütes Essenz erfüllt das Gefäß. Es wird als Herz des neu konstruierten Emblems des Aufstiegs dienen.\"" }
entries[180780] = { ["name"] = "Rezept: Rote Kopfkerze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine rote Kopfkerze herstellt.\nBenötigt Alchemie der Schattenlande\n(1)\nVerkaufspreis:\nRote Kopfkerze\nKosmetisch\nWird beim Anlegen gebunden\nKopf Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:\nBenötigt Schleierstoff , Gemahlene Todesblüte (2), Einbalsamieröl , Destilliertes Todesextrakt" }
entries[180781] = { ["name"] = "Muster: Festlicher rosa Hut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen festlichen rosa Hut herstellt.\nBenötigt Schneiderei der Schattenlande (1)\nVerkaufspreis:\nFestlicher rosa Hut\nKosmetisch\nWird beim Anlegen gebunden\nKopf Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:\nBenötigt Schleierstoff (6), Penumbrafaden (2), Rosa Farbstoff" }
entries[180782] = { ["name"] = "Technik: Faefestmaske", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Faefestmaske herstellt.\nBenötigt Inschriftenkunde der Schattenlande (1)\nVerkaufspreis:\nFaefestmaske\nKosmetisch\nWird beim Anlegen gebunden\nKopf Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:\nBenötigt Leuchtende Tinte (3), Umbraltinte (3), Zwielichtborke (2), Siegelwachs" }
entries[180783] = { ["name"] = "Vorlage: Krone des Rechtschaffenen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Krone des Rechtschaffenen herstellt.\nBenötigt Juwelierskunst der Schattenlande\n(1)\nVerkaufspreis:\nKrone des Rechtschaffenen\nKosmetisch\nWird beim Anlegen gebunden\nKopf Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:\nBenötigt Soleniumerz (4), Umbryl , Oribrant , Wutauge , Formbarer Draht" }
