entries[180945] = { ["name"] = "Gruftgargon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Als treue Wachhunde der Kuratorin patrouillieren diese Gargons durch die Gruften und Katakomben, um Eindringlinge fernzuhalten und Fluchtversuche zu unterbinden.\"\nPakt:\nVenthyr\nZone:\nRevendreth" }
