entries[180948] = { ["name"] = "Kampfgargon Vrednic", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Prinz Renathals treuer Gargon Vrednic begleitet ihn bereits seit Jahrtausenden. In seiner Sinvyrrüstung kann Vrednic allein durch sein Erscheinen alle in Angst und Schrecken versetzen, die ihn mit seinen Reiter in die Schlacht reiten sehen.\"\nPakt:\nVenthyr\nZone:\nRevendreth" }
entries[180949] = { ["name"] = "Animastromstabilisator", ["text"] = "Dauerhafte Aufwertung: Der Schlund\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Macht den Animastromteleporter in Ve'naris Zuflucht verfügbar, mit dem Ihr schnell zum Tremaculum reisen könnt.\nVe'nari muss Euch gegenüber unverbindlich oder positiver eingestellt sein." }
entries[180950] = { ["name"] = "The Maw - Pet Cosmetic - NYI", ["text"] = "Wird beim Aufheben gebunden\n\"Ist zwar sehr niedlich, könnte aber für sämtliches Leben auf Azeroth tödlich sein.\"" }
