entries[180952] = { ["name"] = "Möglichkeitsmatrix", ["text"] = "Dauerhafte Aufwertung: Torghast\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Erlangt ein umfassenderes Verständnis der unendlichen Möglichkeiten der Anima und erweitert so Eure Bonusauswahl in Torghast. Ihr seht bei Benutzung eines Animaschatzes immer mindestens 2 Auswahlmöglichkeiten.\nVe'nari muss Euch gegenüber wertschätzend oder positiver eingestellt sein.\n\"Die Hand des Schicksals kann letztendlich doch geführt werden.\"" }
